1	import java.util.Iterator;
2	import java.util.List;
3	import java.util.Random;
4	
5	/**
6	 * A class representing shared characteristics of animals.
7	 *
8	 * @version 01.03.22
9	 */
10	public abstract class Animal
11	{
12	    // Whether the animal is alive or not.
13	    private boolean alive;
14	    // The animal's field.
15	    private Field field;
16	    // The animal's position in the field.
17	    private Location location;
18	    // Distinguishes between male and female to determine breeding
19	    private boolean isMale;
20	    // whether or not the weather is fog
21	    private boolean fog;
22	    // The animal's food level
23	    private int foodLevel;
24	    //whether the animal has a disease or not
25	    private boolean disease;
26	    // The animal's age.
27	    private int age;
28	
29	    // A shared random number generator to control breeding.
30	    private static final Random rand = Randomizer.getRandom();
31	    
32	    /**
33	     * Create a new animal at location in field.
34	     * 
35	     * @param field The field currently occupied.
36	     * @param location The location within the field.
37	     */
38	    public Animal(Field field, Location location) {
39	        alive = true;
40	        this.field = field;
41	        setLocation(location);
42	        fog = false;
43	        disease = false;
44	    }
45	    
46	    /**
47	     * Make this animal act - that is: make it do
48	     * whatever it wants/needs to do.
49	     * @param newAnimals A list to receive newly born animals.
50	     */
51	    abstract public void act(List<Animal> newAnimals, int time);
52	
53	    /**
54	     * Check whether the animal is alive or not.
55	     * @return true if the animal is still alive.
56	     */
57	    protected boolean isAlive()
58	    {
59	        return alive;
60	    }
61	
62	    /**
63	     * Indicate that the animal is no longer alive.
64	     * It is removed from the field.
65	     */
66	    protected void setDead() {
67	        alive = false;
68	        if(location != null) {
69	            field.clear(location);
70	            location = null;
71	            field = null;
72	        }
73	    }
74	
75	    /**
76	     * Return the animal's location.
77	     * @return The animal's location.
78	     */
79	    protected Location getLocation()
80	    {
81	        return location;
82	    }
83	    
84	    /**
85	     * Place the animal at the new location in the given field.
86	     * @param newLocation The animal's new location.
87	     */
88	    protected void setLocation(Location newLocation) {
89	        if(location != null) {
90	            field.clear(location);
91	        }
92	        location = newLocation;
93	        field.place(this, newLocation);
94	    }
95	    
96	    /**
97	     * Return the animal's field.
98	     * @return The animal's field.
99	     */
100	    protected Field getField()
101	    {
102	        return field;
103	    }
104	
105	    /**
106	     * Return the animal's gender.
107	     * @return True if the animal is male, false if it is female.
108	     */
109	    protected boolean getGender(){return isMale;}
110	
111	    /**
112	     * Randomly assigns an animal a gender
113	     */
114	    protected void setGender() {
115	        Random rand = Randomizer.getRandom();
116	        if (rand.nextInt(2) == 1) {
117	            isMale = true;
118	        }
119	        else {
120	            isMale = false;
121	        }
122	    }
123	
124	    /**
125	     * assigns true to fog field
126	     */
127	    protected void setFog() { fog = true; }
128	
129	    /**
130	     * assigns false to fog field
131	     */
132	    protected void resetFog(){ fog = false; }
133	
134	    /**
135	     * returns the fog field
136	     * @return true if the weather is fog, false if it is not
137	     */
138	    protected boolean getFog() {return fog;}
139	
140	    /**
141	     * takes a food level parameter and assigns it to the foodLevel field
142	     * @param foodLevel the value to be assigned to foodLevel
143	     */
144	    protected void setFoodLevel(int foodLevel){ this.foodLevel = foodLevel; }
145	
146	    /**
147	     * decrements foodLevel by 1
148	     */
149	    protected void decrementHealth(){ foodLevel--; }
150	
151	    /**
152	     * gives an animal a disease
153	     * 1 in 100 chance of assigning true to disease
154	     */
155	    protected void giveDisease() {
156	        Random rand = Randomizer.getRandom();
157	        if (rand.nextInt(101) == 1) {
158	            disease = true;
159	        }
160	    }
161	
162	    /**
163	     * returns whether the animal has a disease or not
164	     * @return true if the animal has a disease, false if they don't
165	     */
166	    protected boolean getDisease() { return disease; }
167	
168	    /**
169	     * assigns false to disease
170	     */
171	    protected void resetDisease() { disease = false; }
172	
173	    /**
174	     * if an animal has a disease, this method spreads it to animals
175	     * in adjacent locations
176	     */
177	    protected void spreadDisease() {
178	        List<Location> adjacent = field.adjacentLocations(getLocation());
179	        Iterator<Location> it = adjacent.iterator();
180	        while(it.hasNext()) {
181	            Location where = it.next();
182	            Object animal = field.getObjectAt(where);
183	            if(animal instanceof Animal) {
184	                Animal diseaseAnimal = (Animal) animal;
185	                diseaseAnimal.giveDisease();
186	                diseaseAnimal.decrementHealth();
187	            }
188	        }
189	    }
190	
191	    /**
192	     * takes an age parameter and assigns it to the age field
193	     * @param age the value to be assigned to the age field
194	     */
195	    protected void setAge(int age) { this.age = age; }
196	
197	    /**
198	     * Generate a number representing the number of births,
199	     * if it can breed.
200	     * @return The number of births (may be zero).
201	     */
202	    protected int breed(int BREEDING_AGE, double BREEDING_PROBABILITY, int MAX_LITTER_SIZE) {
203	        int births = 0;
204	        if(canBreed(BREEDING_AGE) && rand.nextDouble() <= BREEDING_PROBABILITY) {
205	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
206	        }
207	        return births;
208	    }
209	
210	    /**
211	     * Check whether or not this animal is to give birth at this step.
212	     * animals are checked to be: of the same species(class), different genders and
213	     *  of breeding age
214	     * @param BREEDING_AGE the minimum age this animal must be to breed
215	     * @retyrn true if the animal can breed, false if it can not
216	     */
217	    protected boolean giveBirth(int BREEDING_AGE) {
218	        Field field = getField();
219	        List<Location> adjacent = field.adjacentLocations(getLocation());
220	        Iterator<Location> it = adjacent.iterator();
221	        while(it.hasNext()) {
222	            Location where = it.next();
223	            Object animal = field.getObjectAt(where);
224	            if (animal != null) {
225	                if (animal.getClass() == this.getClass()) {
226	                    Animal adjAnimal = (Animal) animal;
227	                    if (this.getGender() != adjAnimal.getGender()) {
228	                        if (age >= BREEDING_AGE) {
229	                            return true;
230	                        }
231	                    }
232	                }
233	            }
234	        }
235	        return false;
236	    }
237	
238	
239	    /**
240	     * checks to see if the animal has reached breeding age
241	     * @param BREEDING_AGE the minimum an animal must be in order to breed
242	     * @return true if the animal is of breeding age
243	     */
244	    protected boolean canBreed(int BREEDING_AGE)
245	    {
246	        return age >= BREEDING_AGE;
247	    }
248	
249	    /**
250	     * make the animal more hungry by decreasing its health
251	     * if the foodLevel is less than or equal to 0, set the animal to dead
252	     */
253	    protected void incrementHunger() {
254	        decrementHealth();
255	        if(foodLevel <= 0) {
256	            setDead();
257	        }
258	    }
259	
260	    /**
261	     * Increase the age. This could result in the animal's death.
262	     */
263	    protected void incrementAge(int MAX_AGE) {
264	        age++;
265	        if(age > MAX_AGE) {
266	            setDead();
267	        }
268	    }
269	
270	}
