11	public class Dingo extends Animal
12	{
13	    // Characteristics shared by all dingoes (class variables).
14	    
15	    // The age at which a dingo can start to breed.
16	    private static final int BREEDING_AGE = 50;
17	    // The age to which a dingo can live.
18	    private static final int MAX_AGE = 700;
19	    // The likelihood of a dingo breeding.
20	    private static final double BREEDING_PROBABILITY = 0.04;
21	    // The maximum number of births.
22	    private static final int MAX_LITTER_SIZE = 3;
23	    // The food value of a single snake. In effect, this is the
24	    // number of steps a dingo can go before it has to eat again.
25	    private static final int SNAKE_FOOD_VALUE = 100;
26	    // A shared random number generator to control breeding.
27	    private static final Random rand = Randomizer.getRandom();
28	
29	    /**
30	     * Create a dingo. A dingo can be created as a newborn (age zero
31	     * and not hungry) or with a random age and food level.
32	     * 
33	     * @param randomAge If true, the dingo will have random age and hunger level.
34	     * @param field The field currently occupied.
35	     * @param location The location within the field.
36	     */
37	    public Dingo(boolean randomAge, Field field, Location location) {
38	        super(field, location);
39	        this.setGender();
40	        if(randomAge) {
41	            setAge(rand.nextInt(MAX_AGE));
42	            setFoodLevel(rand.nextInt(SNAKE_FOOD_VALUE));
43	        }
44	        else {
45	            setAge(0);
46	            setFoodLevel(SNAKE_FOOD_VALUE);
47	        }
48	    }
49	    
50	    /**
51	     * This is what the dingo does most of the time: it hunts for
52	     * snakes. In the process, it might breed, die of hunger,
53	     * or die of old age.
54	     * @param newDingoes A list to return newly born dingoes.
55	     * @param time the current time in the simulation
56	     */
57	    public void act(List<Animal> newDingoes, int time) {
58	        incrementAge(MAX_AGE);
59	        incrementHunger();
60	        if(isAlive() && ((time>=8)&&(time <=24)))
61	        {
62	            if (getDisease()){
63	                spreadDisease();
64	            }
65	            if (giveBirth(BREEDING_AGE)) {
66	                Field field = getField();
67	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
68	                int births = breed(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
69	                for (int b = 0; b < births && free.size() > 0; b++) {
70	                    Location loc = free.remove(0);
71	                    Dingo young = new Dingo(false, field, loc);
72	                    young.setGender();
73	                    newDingoes.add(young);
74	                }
75	            }
76	            Location newLocation = findFood();
77	            if(newLocation == null) {
78	                newLocation = getField().freeAdjacentLocation(getLocation());
79	            }
80	            if(newLocation != null) {
81	                setLocation(newLocation);
82	            }
83	            else {
84	                setDead();
85	            }
86	        }
87	    }
88	
89	    /**
90	     * Look for snakes adjacent to the current location.
91	     * Only the first live snake is eaten.
92	     * If it is a plant, then it is 'trampled'
93	     * @return where food was found, or null if it wasn't.
94	     */
95	    private Location findFood() {
96	        if (getFog()){
97	            if (rand.nextInt(2) == 0) {
98	                Field field = getField();
99	                List<Location> adjacent = field.adjacentLocations(getLocation());
100	                Iterator<Location> it = adjacent.iterator();
101	                while (it.hasNext()) {
102	                    Location where = it.next();
103	                    Object animal = field.getObjectAt(where);
104	                    if (animal instanceof Snake) {
105	                        Snake snake = (Snake) animal;
106	                        if (snake.isAlive()) {
107	                            snake.setDead();
108	                            setFoodLevel(SNAKE_FOOD_VALUE);
109	                            return where;
110	                        }
111	                    } else if (animal instanceof Plant) {
112	                        Plant plant = (Plant) animal;
113	                        if (plant.isAlive()) {
114	                            plant.setDead();
115	                            return where;
116	                        }
117	                    }
118	                }
119	            }
120	            return null;
121	        }
122	        else {
123	            Field field = getField();
124	            List<Location> adjacent = field.adjacentLocations(getLocation());
125	            Iterator<Location> it = adjacent.iterator();
126	            while (it.hasNext()) {
127	                Location where = it.next();
128	                Object animal = field.getObjectAt(where);
129	                if (animal instanceof Snake) {
130	                    Snake snake = (Snake) animal;
131	                    if (snake.isAlive()) {
132	                        snake.setDead();
133	                        setFoodLevel(SNAKE_FOOD_VALUE);
134	                        return where;
135	                    }
136	                }
137	                else if (animal instanceof Plant){
138	                    Plant plant = (Plant) animal;
139	                    if(plant.isAlive()) {
140	                        plant.setDead();
141	                        return where;
142	                    }
143	                }
144	            }
145	            return null;
146	        }
147	    }
148	}
