5	/**
6	 * A simple model of an eagle.
7	 * Eagles age, move, eat snakes and rats, and die.
8	 *
9	 * @version 01.03.22
10	 */
11	
12	public class Eagle extends Animal
13	{
14	    // Characteristics shared by all eagles (class variables).
15	
16	    // The age at which an eagle can start to breed.
17	    private static final int BREEDING_AGE = 50;
18	    // The age to which an eagle can live.
19	    private static final int MAX_AGE = 700;
20	    // The likelihood of an  eagle breeding.
21	    private static final double BREEDING_PROBABILITY = 0.1;
22	    // The maximum number of births.
23	    private static final int MAX_LITTER_SIZE = 11;
24	    // The food value of a single rat. In effect, this is the
25	    // number of steps an eagle can go before it has to eat again.
26	    private static final int RAT_FOOD_VALUE = 40;
27	    // The food value of a single snake. In effect, this is the
28	    // number of steps an eagle can go before it has to eat again.
29	    private static final int SNAKE_FOOD_VALUE = 60;
30	    // A shared random number generator to control breeding.
31	    private static final Random rand = Randomizer.getRandom();
32	
33	    /**
34	     * Create an eagle. An eagle can be created as a newborn (age zero
35	     * and not hungry) or with a random age and food level.
36	     *
37	     * @param randomAge If true, the eagle will have random age and hunger level.
38	     * @param field The field currently occupied.
39	     * @param location The location within the field.
40	     */
41	    public Eagle(boolean randomAge, Field field, Location location) {
42	        super(field, location);
43	        this.setGender();
44	        if(randomAge) {
45	            setAge(rand.nextInt(MAX_AGE));
46	            setFoodLevel(rand.nextInt(SNAKE_FOOD_VALUE));
47	        }
48	        else {
49	            setAge(0);
50	            setFoodLevel(SNAKE_FOOD_VALUE);
51	        }
52	    }
53	
54	    /**
55	     * This is what the eagle does most of the time: it hunts for
56	     * rats and snakes. In the process, it might breed, die of hunger,
57	     * or die of old age.
58	     * @param newEagles A list to return newly born eagles.
59	     * @param time the current time in the simulation
60	     */
61	    public void act(List<Animal> newEagles, int time) {
62	        incrementAge(MAX_AGE);
63	        incrementHunger();
64	        if(isAlive() && ((time >= 6)&&(time <= 22))) {
65	            if (getDisease()){
66	                spreadDisease();
67	            }
68	            if (giveBirth(BREEDING_AGE)) {
69	                Field field = getField();
70	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
71	                int births = breed(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
72	                for (int b = 0; b < births && free.size() > 0; b++) {
73	                    Location loc = free.remove(0);
74	                    Eagle young = new Eagle(false, field, loc);
75	                    young.setGender();
76	                    newEagles.add(young);
77	                }
78	            }
79	            Location newLocation = findFood();
80	            if(newLocation == null) {
81	                newLocation = getField().freeAdjacentLocation(getLocation());
82	            }
83	            if(newLocation != null) {
84	                setLocation(newLocation);
85	            }
86	            else {
87	                setDead();
88	            }
89	
90	        }
91	
92	    }
93	
94	    /**
95	     * Look for rats and snakes adjacent to the current location.
96	     * Only the first live rat or snake is eaten.
97	     * If it is a plant, then it is 'trampled'
98	     * @return Where food was found, or null if it wasn't.
99	     */
100	    private Location findFood() {
101	        if (getFog() && (rand.nextInt(2) == 0)) {
102	            Field field = getField();
103	            List<Location> adjacent = field.adjacentLocations(getLocation());
104	            Iterator<Location> it = adjacent.iterator();
105	            while(it.hasNext()) {
106	                Location where = it.next();
107	                Object animal = field.getObjectAt(where);
108	                if(animal instanceof Snake) {
109	                    Snake snake = (Snake) animal;
110	                    if(snake.isAlive()) {
111	                        snake.setDead();
112	                        setFoodLevel(SNAKE_FOOD_VALUE);
113	                        return where;
114	                    }
115	                }
116	                else if(animal instanceof Rat) {
117	                    Rat rat = (Rat) animal;
118	                    if(rat.isAlive()) {
119	                        rat.setDead();
120	                        setFoodLevel(RAT_FOOD_VALUE);
121	                        return where;
122	                    }
123	                }
124	                else if (animal instanceof Plant) {
125	                    Plant plant = (Plant) animal;
126	                    if(plant.isAlive()) {
127	                        plant.setDead();
128	                        return where;
129	                    }
130	                }
131	            }
132	            return null;
133	        }
134	        else {
135	            Field field = getField();
136	            List<Location> adjacent = field.adjacentLocations(getLocation());
137	            Iterator<Location> it = adjacent.iterator();
138	            while (it.hasNext()) {
139	                Location where = it.next();
140	                Object animal = field.getObjectAt(where);
141	                if (animal instanceof Snake) {
142	                    Snake snake = (Snake) animal;
143	                    if (snake.isAlive()) {
144	                        snake.setDead();
145	                        setFoodLevel(SNAKE_FOOD_VALUE);
146	                        return where;
147	                    }
148	                }
149	                else if(animal instanceof Rat) {
150	                    Rat rat = (Rat) animal;
151	                    if(rat.isAlive()) {
152	                        rat.setDead();
153	                        setFoodLevel(RAT_FOOD_VALUE);
154	                        return where;
155	                    }
156	                }
157	                else if (animal instanceof Plant){
158	                    Plant plant = (Plant) animal;
159	                    if(plant.isAlive()) {
160	                        plant.setDead();
161	                        return where;
162	                    }
